using System;using System.IO;using System.IO.Compression;using System.Reflection;using System.Collections;using System.Collections.Generic;using System.Diagnostics;using System.Security.Cryptography;using System.Web.Script.Serialization;using System.Windows;using System.Windows.Media;using System.Windows.Media.Imaging;
public static class ColourReview{
 static BindingFlags F=BindingFlags.Instance|BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic;static List<string> checks=new List<string>();static object C(object o,string n,params object[] a){try{return o.GetType().GetMethod(n,F).Invoke(o,a);}catch(TargetInvocationException e){throw e.InnerException??e;}}static void Check(bool v,string n){if(!v)throw new Exception(n);if(!checks.Contains(n))checks.Add(n);}static string Hash(string p){using(var h=SHA256.Create())using(var s=File.OpenRead(p))return BitConverter.ToString(h.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
 static byte[] Raw(Assembly a,int row,int index){using(var s=a.GetManifestResourceStream("WhiteDragon.Motion"+row))using(var r=new BinaryReader(s)){Check(r.ReadUInt32()==0x31504457&&r.ReadInt32()==640&&r.ReadInt32()==360,"valid source frame geometry");int count=r.ReadInt32();Check(index>=0&&index<count,"stored frame index is in range");s.Position=16+index*8;int off=r.ReadInt32(),n=r.ReadInt32();s.Position=off;using(var slice=new MemoryStream(r.ReadBytes(n)))using(var g=new GZipStream(slice,CompressionMode.Decompress)){byte[] p=new byte[640*360*4];int used=0,k;while(used<p.Length&&(k=g.Read(p,used,p.Length-used))>0)used+=k;Check(used==p.Length,"complete original frame decode");return p;}}}
 static bool Same(byte[] a,byte[] b){for(int i=0;i<a.Length;i++)if(a[i]!=b[i])return false;return true;}static void Save(byte[] p,string file){var b=BitmapSource.Create(640,360,96,96,PixelFormats.Pbgra32,null,p,2560);b.Freeze();using(var f=File.Create(file)){var e=new PngBitmapEncoder();e.Frames.Add(BitmapFrame.Create(b));e.Save(f);}}
 [STAThread]public static int Main(string[] args){string target=Path.GetFullPath(args[0]),folder=Path.GetFullPath(args[1]);Directory.CreateDirectory(folder);Directory.CreateDirectory(Path.Combine(folder,"frames"));var report=new Dictionary<string,object>{{"candidate_sha256",Hash(target)}};object smooth=null;
 try{var a=Assembly.LoadFrom(target);var method=a.GetType("WhiteDragon.MotionColorGrade",true).GetMethod("Apply");var stack=a.GetType("WhiteDragon.BookStackConsistency",true).GetMethod("Apply");long protectedPixels=0,changedPixels=0;double elapsed=0,maxMs=0;int frames=0,maxDelta=0;
  for(int row=22;row<=27;row++)for(int i=0;i<300;i++){
   byte[] raw=Raw(a,row,i),p=(byte[])raw.Clone();var watch=Stopwatch.StartNew();method.Invoke(null,new object[]{row,i,p});double ms=watch.Elapsed.TotalMilliseconds;elapsed+=ms;maxMs=Math.Max(maxMs,ms);bool alpha=true,valid=true,protectedOk=true;
   for(int at=0;at<raw.Length;at+=4){int alphaValue=raw[at+3];alpha&=p[at+3]==alphaValue;valid&=p[at]<=alphaValue&&p[at+1]<=alphaValue&&p[at+2]<=alphaValue;bool altered=p[at]!=raw[at]||p[at+1]!=raw[at+1]||p[at+2]!=raw[at+2];if(altered)changedPixels++;for(int ch=0;ch<3;ch++)maxDelta=Math.Max(maxDelta,Math.Abs(p[at+ch]-raw[at+ch]));
    bool protect=alphaValue==0;if(alphaValue>0){int rr=(raw[at+2]*255+alphaValue/2)/alphaValue,gg=(raw[at+1]*255+alphaValue/2)/alphaValue,bb=(raw[at]*255+alphaValue/2)/alphaValue;int low=Math.Min(rr,Math.Min(gg,bb));protect=low<=130||Math.Max(rr,Math.Max(gg,bb))-low>=58||rr-bb>=22;}if(protect){protectedPixels++;protectedOk&=!altered;}
   }
   Check(alpha,"all graded frames preserve every alpha byte");Check(valid,"all graded frames remain valid premultiplied pixels");Check(protectedOk,"dark linework saturated colours and warm skin cores stay unchanged");if(i==0||i>=294)Check(Same(raw,p),"all first and six final moving-tail frames stay exact");if(i%3==0)Save(p,Path.Combine(folder,"frames",row+"-"+i.ToString("000")+".png"));frames++;
  }
  foreach(int row in new int[]{0,3,12,14,15,16,17,18,19,20,21}){byte[] raw=Raw(a,row,0),p=(byte[])raw.Clone();method.Invoke(null,new object[]{row,120,p});Check(Same(raw,p),"unselected action rows remain bit exact");}
  report["frames_checked"]=frames;report["protected_pixels_checked"]=protectedPixels;report["changed_neutral_pixels"]=changedPixels;report["max_channel_change"]=maxDelta;report["mean_grade_ms"]=elapsed/frames;report["max_grade_ms"]=maxMs;Check(elapsed/frames<5,"grade stays within bounded worker cost");
  Dictionary<string,object> document;using(var s=a.GetManifestResourceStream("WhiteDragon.MotionSpec"))using(var r=new StreamReader(s))document=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(r.ReadToEnd());var rows=(Dictionary<string,object>)document["rows"];
  smooth=Activator.CreateInstance(a.GetType("WhiteDragon.SmoothMotion"));int probes=0;
  foreach(int row in new int[]{0,19,22,23,24,25,26,27})foreach(double time in new double[]{0,1000,2500,4500,4900}){
   Check((bool)C(smooth,"EnsureSample",row,time,10000),"native decoder prepares colour sample");int index=(int)C(smooth,"GetSampleIndex",row,time);var meta=(Dictionary<string,object>)rows[row.ToString()];var map=(ArrayList)meta["map"];int stored=Convert.ToInt32(map[index]);byte[] expected=Raw(a,row,stored);stack.Invoke(null,new object[]{row,stored,expected});method.Invoke(null,new object[]{row,stored,expected});byte[] actual=new byte[expected.Length];Check((bool)C(smooth,"TryCopyExact",row,time,actual),"native decoder publishes exact requested sample");Check(Same(expected,actual),"cache receives exactly one book repair and one grade");probes++;
  }
  report["native_decode_probes"]=probes;C(smooth,"Dispose");report["worker_stopped"]=smooth.GetType().GetProperty("WorkerStopped").GetValue(smooth,null);Check((bool)report["worker_stopped"],"colour decoder exits cleanly");report["ok"]=true;
 }catch(Exception e){report["ok"]=false;report["error"]=e.ToString();}finally{if(smooth!=null)C(smooth,"Dispose");report["checks"]=checks;report["scope"]="Exact compiled grade for every frame of six selected rows; alpha, premultiplication, protected colour classes, native decode/cache integration and exact moving tails. Corresponding-region and subjective checks are separate. No installed state or original media changes.";File.WriteAllText(Path.Combine(folder,"colour-review.json"),new JavaScriptSerializer().Serialize(report));}return report.ContainsKey("ok")&&(bool)report["ok"]?0:1;
 }
}
